    lib.hm.dag.entryAfter ["writeBoundary"] ''
      ${grok-cfg.mcpSeed}
    ''
  );

  home.activation.agySettingsSeed = lib.mkIf (!isMinimal) (
    lib.hm.dag.entryAfter ["writeBoundary"] ''
