      if [ -z "$ZELLIJ" ]; then
        session-picker; exit
      fi
      eval "$(fzf --zsh)"
      eval "$(zoxide init zsh)"

      echo -e "\033[1;34m"
      echo " _   _     _               "
      echo "| |_| |__ (_)_  _____  ___ "
      echo "| __| '_ \| \ \/ / _ \/ __|"
      echo "| |_| | | | |>  < (_) \__ \\"
      echo " \__|_| |_|_/_/\_\___/|___/"
      echo -e "\033[0m"

