          local name branch dirty
          name=$(basename "$repo")
          branch=$(git branch --show-current 2>/dev/null)
          [[ -n $(git status --porcelain 2>/dev/null | head -1) ]] && dirty="*"
          title="''${name}:''${branch}''${dirty}"
