  # first ssh/git op that unlocks a key parks it in the agent for the rest of
  # the boot. enableDefaultConfig = false stops home-manager writing its
  # legacy `Host *` defaults (and a deprecation warning) into ~/.ssh/config.
  programs.ssh = {
    enable = true;
    enableDefaultConfig = false;
    settings."*".AddKeysToAgent = "yes";
  };

  programs.git = {
    enable = true;
    includes = [
      {
        # The trailing slash matches all repositories beneath this directory.
        condition = "gitdir:~/src/github.com/bookcreator/";
        contents.user.email = "thom@bookcreator.com";
      }
    ];
    settings = {
      user.name = "Thom Leggett";
      user.email = "thom@tteggel.org";
      core.fsync = "committed";
      core.pager = "delta";
      interactive.diffFilter = "delta --color-only";
      delta = {
        navigate = true;
        side-by-side = true;
        line-numbers = true;
      };
      merge.conflictstyle = "diff3";
      diff.colorMoved = "default";
      difftool.difftastic.cmd = ''difft "$LOCAL" "$REMOTE"'';
      difftool.prompt = false;
      alias = {
        dft = "difftool -t difftastic";
        st = "status";
        co = "checkout";
        br = "branch";
        ci = "commit";
        lg = "log --graph --pretty=format:'%Cred%h%Creset -%C(yellow)%d%Creset %s %Cgreen(%cr) %C(bold blue)<%an>%Creset' --abbrev-commit";
      };
    };
  };
}

